// Explicit verification only: consumes fixtures generated by browser_meter_probe.
// These are trusted compiler outputs, not accepted application artifacts. The
// official artifact validator/packager and other effects are still in development.
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import assert from "node:assert/strict";
import { observe } from "./probe-run.mjs";

const directory = process.argv[2];
if (!directory) throw new Error("usage: node probe.mjs FIXTURE_DIRECTORY");
const budgets = (await readFile(join(directory, "budgets.txt"), "utf8")).split("\n").map(Number);
const module = await WebAssembly.compile(await readFile(join(directory, "metered.wasm")));
for (const budget of budgets) {
  const actual = await observe(module, budget);
  assert.equal(actual, await readFile(join(directory, `${budget}.golden`), "utf8"), `budget ${budget}`);
}
console.log(`${budgets.length} native/Node meter observations match (outcome, remaining fuel, host call positions and Unicode output)`);
